:root {
  --bg-card: #1e2530;
  --bg-header: #252e3e;
  --bg-section: #2a3345;
  --bg-check-pass: #1a3a2e;
  --bg-check-warn: #3a2e14;
  --accent-green: #3ecf82;
  --accent-yellow: #f0b429;
  --accent-blue: #5b9cf6;
  --text-primary: #e8edf5;
  --text-secondary: #8a97b0;
  --text-muted: #5a6780;
  --border-subtle: #344060;
  --status-pass-bg: #3ecf82;
  --status-pass-text: #0a1f14;
  --cert-bg: #5b9cf6;
  --cert-text: #0a1428;
}

article.gear-tag {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  width: 420px;
  overflow: hidden;
  font-size: 13px;
}

.tag-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-subtle);
}

.tag-icon {
  font-size: 22px;
  line-height: 1;
}

.tag-title {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.tag-title h1 {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.tag-subtitle {
  font-size: 10px;
  font-weight: 500;
  color: var(--text-secondary);
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tag-status {
  background-color: var(--status-pass-bg);
  color: var(--status-pass-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 3px 8px;
  border-radius: 5px;
}

.gear-info {
  display: flex;
  flex-direction: column;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
  gap: 0;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 0;
  border-bottom: 1px solid var(--border-subtle);
}

.info-row:last-child {
  border-bottom: none;
}

.info-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.info-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.info-value.mono {
  font-size: 11px;
  color: var(--accent-blue);
  letter-spacing: 0.04em;
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
}

.check-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 7px 4px;
  border-radius: 7px;
  border: 1px solid transparent;
}

.check-item.pass {
  background-color: var(--bg-check-pass);
  border-color: var(--accent-green);
}

.check-item.warn {
  background-color: var(--bg-check-warn);
  border-color: var(--accent-yellow);
}

.check-icon {
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
}

.check-item.pass .check-icon {
  color: var(--accent-green);
}

.check-item.warn .check-icon {
  color: var(--accent-yellow);
}

.check-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.check-item.pass .check-label {
  color: var(--accent-green);
}

.check-item.warn .check-label {
  color: var(--accent-yellow);
}

.tag-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background-color: var(--bg-section);
}

.footer-dates {
  display: flex;
  gap: 20px;
}

.date-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.date-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.date-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.cert-badge {
  background-color: var(--cert-bg);
  color: var(--cert-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 20px;
}
